/// <summary>
/// AVA/WEN/2025/05/15   AVA_013002_ResourceCalendar
/// </summary>
class AVAUpdateResourceCalendarController  extends SysOperationServiceController
{
}

Method.Source:
public static AVAUpdateResourceCalendarController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    AVAUpdateResourceCalendarController controller;
    controller = new AVAUpdateResourceCalendarController();
    controller.parmExecutionMode(_executionMode);
    return controller;
}

public static void main(Args _args)
{
    AVAUpdateResourceCalendarController controller;
    AVAUpdateResourceCalendarContract   contract;
    WrkCtrTable wrkCtrTable;
    KCS_PTMToolTable toolTable;
    controller = AVAUpdateResourceCalendarController::construct();
    controller.parmArgs(_args);

    if (_args.record() && _args.dataset() == tableNum(WrkCtrTable))
    {
        wrkCtrTable = _args.record();
        contract = controller.getDataContractObject();
        contract.parmResourceId(wrkCtrTable.WrkCtrId);
    }
    else if (_args.record() && _args.dataset() == tablenum(KCS_PTMToolTable))
    {
        toolTable = _args.record();
        contract = controller.getDataContractObject();
        contract.parmResourceId(toolTable.ToolId);
        contract.parmFromReleaseStatus(true);
        contract.parmFromDate(str2Date(_args.parm(), 123));
        controller.parmShowDialog(false);

    }
    controller.startOperation();
}

public boolean parmLoadFromSysLastValue(boolean _loadFromSysLastValue = loadFromSysLastValue)
{    
    return false;
}
